// Qualitative, idealized teaching models. No real electrical equipment is needed.
export const magnetExperiments={
 poles:{name:'Push and pull',icon:'🧲',intro:'Choose the ends that face each other. Watch the magnets.',fact:'Opposite magnetic poles attract. Like poles repel.'},
 materials:{name:'Material detective',icon:'🔎',intro:'Pick a sample. Will this ordinary magnet pull it?',fact:'Iron is strongly attracted. Wood, copper and aluminium are not strongly attracted to an ordinary magnet.'},
 coil:{name:'Switchable electromagnet',icon:'⚡',intro:'Tap the switch. The coil can lift iron washers.',fact:'Current in a coil produces a magnetic field. More turns can strengthen this model electromagnet at the same current.'},
 generator:{name:'Magnet and coil generator',icon:'💡',intro:'Move the magnet through the coil with one tap. Or hold it still.',fact:'Changing magnetic flux through a coil induces voltage. Holding the magnet still does not sustain it.'}
};
export function magnetStart(){return {poles:'opposite',sample:'iron',power:false,turns:1,motion:'still',tested:false};}
export function magnetAction(raw,action){const s={...raw};if(action==='reset')return magnetStart();s.tested=true;if(action==='opposite'||action==='same')s.poles=action;if(['iron','wood','copper','aluminium'].includes(action))s.sample=action;if(action==='switch')s.power=!s.power;if(action==='turns')s.turns=s.turns===1?3:1;if(['in','out','still'].includes(action))s.motion=action;return s;}
export function magnetView(id,s=magnetStart()){
 const e=magnetExperiments[id]||magnetExperiments.poles;let result='',art='',actions=[];
 if(id==='poles'){const pull=s.poles==='opposite';result=pull?'Opposite ends: the magnets pull together.':'Same ends: the magnets push apart.';art=pull?'attract':'repel';actions=[['🧲 N + S / Pull','opposite'],['🧲 N + N / Push','same']];}
 if(id==='materials'){const yes=s.sample==='iron';result=s.sample==='iron'?'Iron washer: pulled toward the magnet.':s.sample[0].toUpperCase()+s.sample.slice(1)+': no strong pull in this model. Not every metal sticks!';art='sample-'+s.sample;actions=[['⚙ Iron washer','iron'],['🪵 Wood block','wood'],['▱ Copper piece','copper'],['▰ Aluminium piece','aluminium']];}
 if(id==='coil'){result=s.power?'Circuit closed. Current flows. '+(s.turns===1?'One turn lifts one model washer.':'Three turns lift three model washers.'):'Circuit open. No current. The model washers rest on the tray.';art=s.power?'coil-'+s.turns:'coil-off-'+s.turns;actions=[[s.power?'○ Switch OFF':'⚡ Switch ON','switch'],[s.turns===1?'➰ Try 3 turns':'➰ Try 1 turn','turns']];}
 if(id==='generator'){result=s.motion==='still'?'Magnet held still: no sustained voltage. The lamp is off.':s.motion==='in'?'Magnet moving IN: a voltage pulse lights the lamp.':'Magnet moving OUT: the voltage reverses. The lamp lights for this pulse too.';art='generator-'+s.motion;actions=[['→ Move magnet IN','in'],['■ Hold magnet STILL','still'],['← Move magnet OUT','out']];}
 return {title:e.name,text:s.tested?result:e.intro,result,fact:e.fact,art,actions:[...actions,['↻ Start again','reset']]};
}
export const magnetArtKeys=['attract','repel','sample-iron','sample-wood','sample-copper','sample-aluminium','coil-off-1','coil-off-3','coil-1','coil-3','generator-still','generator-in','generator-out'];
export function magnetArt(key){
 const label=(x,y,t,size=20)=>`<text x="${x}" y="${y}" fill="#17384a" font-family="sans-serif" font-size="${size}" font-weight="bold" text-anchor="middle">${t}</text>`;
 const magnet=(x,y,a='N',b='S')=>`<rect x="${x}" y="${y}" width="64" height="42" rx="4" fill="#c4ced8" stroke="#17384a" stroke-width="3"/>${label(x+16,y+28,a)}${label(x+48,y+28,b)}<path d="M${x+32} ${y}v42" stroke="#17384a" stroke-width="2"/>`;
 let art='';
 if(key==='attract'||key==='repel'){art=magnet(30,67)+magnet(245,67,key==='attract'?'N':'S',key==='attract'?'S':'N')+label(170,94,key==='attract'?'→ ←':'← →',32)+label(170,145,key==='attract'?'PULL TOGETHER':'PUSH APART');}
 else if(key.startsWith('sample-')){const sample=key.slice(7),pull=sample==='iron';art=magnet(28,65)+label(175,95,pull?'←':'×',35)+`<rect x="240" y="66" width="52" height="44" rx="6" fill="#d8c7a5" stroke="#17384a" stroke-width="3"/>`+label(170,150,sample.toUpperCase())+label(170,177,pull?'PULLED':'NO STRONG PULL',16);}
 else if(key.startsWith('coil-')){const on=!key.startsWith('coil-off'),n=key.endsWith('-3')?3:1;art=`<path d="M45 60v-30h240v120H45v-55" fill="none" stroke="#17384a" stroke-width="4"/><path d="M45 60l${on?'0 35':'22 25'}" stroke="#17384a" stroke-width="6"/><rect x="120" y="22" width="90" height="16" fill="#fffbed"/>`+label(165,35,'+   −',18)+`<rect x="125" y="64" width="100" height="25" rx="8" fill="#c4ced8" stroke="#17384a" stroke-width="3"/>`;for(let i=0;i<n;i++)art+=`<ellipse cx="${175+(i-(n-1)/2)*28}" cy="76" rx="8" ry="23" fill="none" stroke="#906b38" stroke-width="4"/>`;for(let i=0;i<3;i++)art+=`<circle cx="${145+i*26}" cy="${on&&i<n?112:158}" r="9" fill="#fffbed" stroke="#17384a" stroke-width="3"/>`;art+=label(170,192,on?'ON / LIFT':'OFF / REST',16);}
 else {const motion=key.split('-')[1],on=motion!=='still';art=magnet(motion==='in'?115:25,74)+`<path d="M200 65v-40h95v135h-95v-45" fill="none" stroke="#17384a" stroke-width="4"/>`;for(let i=0;i<4;i++)art+=`<ellipse cx="${183+i*11}" cy="96" rx="8" ry="33" fill="none" stroke="#906b38" stroke-width="3"/>`;art+=`<circle cx="295" cy="95" r="23" fill="${on?'#f5d66e':'#c4ced8'}" stroke="#17384a" stroke-width="3"/>`+label(295,102,on?'ON':'OFF',14)+label(100,53,motion==='in'?'→ IN':motion==='out'?'← OUT':'■ STILL',20)+label(170,180,motion==='in'?'+ PULSE':motion==='out'?'− PULSE':'NO PULSE');}
 return '<svg xmlns="http://www.w3.org/2000/svg" width="340" height="210" viewBox="0 0 340 210"><rect width="340" height="210" rx="12" fill="#edf4df"/>'+art+'</svg>';
}
